/* English presentation layer. Internal IDs, selectors, values and editorial data remain stable. */
(()=>{'use strict';if(document.documentElement.lang!=='en')return;const MAP=window.EDITIONS_EN||{},norm=s=>String(s).replace(/\s+/g,' ').trim();
let partial;function text(s){if(!s||!s.trim())return s;const n=norm(s);if(MAP[n])return s.replace(s.trim(),MAP[n]);if(!partial)partial=Object.keys(MAP).filter(k=>(k.length>=5||['hoch','neu','und','oder','von','bis','mit','für','zum','Mai','Mär'].includes(k))&&k.length<180&&MAP[k]!==k&&!/[<>{}]/.test(k)).sort((a,b)=>b.length-a.length);let result=s;for(const k of partial){if(result.includes(k))result=result.replace(new RegExp((/^[\p{L}\p{N}_]/u.test(k)?'(?<![\\p{L}\\p{N}_])':'')+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+(/[\p{L}\p{N}_]$/u.test(k)?'(?![\\p{L}\\p{N}_])':''),'gu'),()=>MAP[k])}return result}
function codeProse(s){return s.replace(/<!--([\s\S]*?)-->/g,(all,body)=>'<!--'+text(body)+'-->').replace(/^(\s*[│├└─ ]*[a-zA-Z0-9_.-]+\/?[ \t]{2,})([^<>\n]+)$/gm,(all,prefix,body)=>prefix+text(body))} const skip=n=>{const p=n.parentElement;return !p||p.closest('script,style,code,pre,textarea,[data-original-language]')};
function element(root){if(root.nodeType===3){if(root.parentElement?.closest('code,pre')){const t=codeProse(root.nodeValue);if(t!==root.nodeValue)root.nodeValue=t}else if(!skip(root)){const t=text(root.nodeValue);if(t!==root.nodeValue)root.nodeValue=t}return}if(root.nodeType!==1&&root.nodeType!==9)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode())if(n.parentElement?.closest('code,pre')){const t=codeProse(n.nodeValue);if(t!==n.nodeValue)n.nodeValue=t}else if(!skip(n)){const t=text(n.nodeValue);if(t!==n.nodeValue)n.nodeValue=t}if(root.nodeType===1){for(const el of [root,...root.querySelectorAll('[alt],[title],[aria-label],[placeholder]')])for(const attr of ['alt','title','aria-label','placeholder'])if(el.hasAttribute(attr)){const value=el.getAttribute(attr),t=text(value);if(t!==value)el.setAttribute(attr,t)}}}
let busy=false;const observer=new MutationObserver(records=>{if(busy)return;busy=true;observer.disconnect();for(const r of records){if(r.type==='characterData')element(r.target);else if(r.type==='attributes')element(r.target);else for(const n of r.addedNodes)element(n)}observer.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','alt','title','placeholder']});busy=false});
observer.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['aria-label','alt','title','placeholder']});
function plain(s){return String(s).split('\n').map(line=>{if(MAP[norm(line)])return text(line);const i=line.indexOf(':');if(i>=0&&i<90){const prefix=line.slice(0,i),translated=MAP[norm(prefix)];if(translated)return translated+line.slice(i)}return text(line)}).join('\n')}
function html(s,type){const svg=type.includes('svg');const doc=new DOMParser().parseFromString(s,svg?'image/svg+xml':'text/html');if(doc.querySelector('parsererror'))return s;element(doc);if(svg)return new XMLSerializer().serializeToString(doc.documentElement);doc.documentElement.lang='en';return '<!doctype html>'+doc.documentElement.outerHTML}
function values(x){if(typeof x==='string')return /^[A-Za-z0-9_./:#%+@?=&-]+$/.test(x)?x:(MAP[norm(x)]||x);if(Array.isArray(x))return x.map(values);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,values(v)]));return x}
const NativeBlob=window.Blob;window.Blob=class extends NativeBlob{constructor(parts,options={}){const type=options.type||'';super(parts.map(part=>{if(typeof part!=='string')return part;if(type.includes('json')){try{return JSON.stringify(values(JSON.parse(part)),null,2)}catch{return part}}if(type.includes('html')||type.includes('svg'))return html(part,type);if(type.startsWith('text/'))return plain(part);return part}),options)}};
window.addEventListener('beforeprint',()=>element(document.body));document.addEventListener('DOMContentLoaded',()=>element(document.body));window.EDITION_EN={text,translate:()=>element(document.body)};
})();
